import sys, json

after = json.load(sys.stdin)
baseline = json.load(open('baseline-packages.json'))

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

print('CHANGES:')
for key in sorted(set(b) | set(a)):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        print(f'  {key[0]:20s} {key[1]:40s} {bv:10s} -> {av}')

print()
print('UNCHANGED:')
for key in sorted(set(b) & set(a)):
    if b[key] == a[key]:
        print(f'  {key[0]:20s} {key[1]:40s} {b[key]}')
"

